import"./chunk-7CGTOI24.js";var e={slug:"review-pecadores-ryan-coogler",title:"Review: Pecadores, de Ryan Coogler, \xE9 blues, terror e cinema grande",dek:"Michael B. Jordan em dose dupla, vampiros no Mississippi dos anos 1930 e uma das sequ\xEAncias musicais mais bonitas do cinema recente. Revisitamos o filme.",section:"filmes",kind:"review",tags:["Terror","Ryan Coogler","Warner"],date:"2026-10-24",hero:{ref:"movie:1233413",pick:0,alt:"Michael B. Jordan em cena de Pecadores"},score:9,verdict:{summary:"Um filme de g\xEAnero com ambi\xE7\xE3o de \xE9pico. Pecadores usa o terror de vampiro para falar de m\xFAsica, comunidade e liberdade, e entrega isso com um prazer de cinema raro.",good:["Michael B. Jordan excelente como os g\xEAmeos Smoke e Stack","Uso da m\xFAsica como motor da hist\xF3ria","Primeira metade paciente, que faz o terror valer"],bad:["Ter\xE7o final mais convencional que o resto","Alguns coadjuvantes merecem mais tempo"]},body:[{p:"*Pecadores* chegou aos cinemas brasileiros em 17 de abril de 2025 e virou assunto rapidamente. Escrito e dirigido por Ryan Coogler, o filme \xE9 daqueles que crescem na segunda vez. Voltamos a ele agora, longe do barulho do lan\xE7amento."},{ficha:"movie:1233413"},{h2:"Dois irm\xE3os, uma noite"},{p:"Estamos no Delta do Mississippi, em 1932. Os g\xEAmeos Smoke e Stack, ambos vividos por Michael B. Jordan, voltam de Chicago com dinheiro e um plano: abrir um juke joint, um sal\xE3o de m\xFAsica e dan\xE7a para a comunidade negra da regi\xE3o. Para a noite de estreia, contam com o primo Sammie, um jovem guitarrista vivido por Miles Caton, cujo blues \xE9 bom demais para passar despercebido."},{p:"O que chega atra\xEDdo pela m\xFAsica \xE9 Remmick, interpretado por Jack O'Connell, e o filme vira, aos poucos, uma hist\xF3ria de vampiros. A paci\xEAncia de Coogler para montar esse mundo antes do terror \xE9 o que faz o resto funcionar."},{img:"movie:1233413",pick:2,caption:"O juke joint \xE9 o cora\xE7\xE3o do filme. Imagem de divulga\xE7\xE3o."},{h2:"A m\xFAsica como protagonista"},{p:"H\xE1 uma sequ\xEAncia no meio do filme em que a m\xFAsica de Sammie atravessa o tempo e re\xFAne gera\xE7\xF5es de artistas no mesmo sal\xE3o. \xC9 o momento em que *Pecadores* deixa claro o que quer dizer: a m\xFAsica \xE9 mem\xF3ria, resist\xEAncia e tamb\xE9m uma porta que pode ser aberta para o lado errado."},{quote:"Coogler filma o blues como quem filma um ritual. Quando os vampiros chegam, j\xE1 entendemos o que est\xE1 em jogo."},{h2:"Elenco"},{p:"Michael B. Jordan diferencia os g\xEAmeos com gestos e postura, sem recorrer a truques f\xE1ceis. Wunmi Mosaku, como Annie, e Hailee Steinfeld, como Mary, d\xE3o peso emocional a um roteiro que poderia ficar s\xF3 no espet\xE1culo. O ter\xE7o final \xE9 mais convencional, com a\xE7\xE3o e sangue no lugar da tens\xE3o, mas n\xE3o compromete."},{h2:"Veredito"},{p:"*Pecadores* \xE9 um filme de autor que n\xE3o tem vergonha de ser filme de g\xEAnero. Diverte, assusta e fica na cabe\xE7a. Nota 9."},{p:"Gosta de terror com algo a dizer? Veja os [jogos de terror que recomendamos para 2026](/artigo/10-jogos-de-terror-para-jogar-em-2026)."}]};var a={source:"TMDB + IGDB",updatedAt:"2026-11-10",calendar:[],games:{},movies:{1233413:{id:1233413,title:"Pecadores",original:"Sinners",overview:"Dispostos a deixar suas vidas conturbadas para tr\xE1s, irm\xE3os g\xEAmeos retornam \xE0 sua cidade natal para recome\xE7ar suas vidas do zero, quando descobrem que um mal ainda maior est\xE1 \xE0 espera deles para receb\xEA-los de volta.",poster:"/v0Ljeti537c6cNKweuEN0iaU3x4.jpg",backdrops:["/nAxGnGHOsfzufThz20zgmRwKur3.jpg","/j7KqDRzjbvIjDv7cdHz9G3ZYEQy.jpg","/7dQTILcUKw8chDiLj8TgPXxRuED.jpg","/mTSL8FmdAO1YiPQzr0fUacCUS0H.jpg","/sqkSVOijtdqP1yPQ8vZidxXFauQ.jpg"],runtime:138,genres:["Terror","A\xE7\xE3o","Thriller"],cert:"16",release:"2025-04-17",world:"2025-04-16",directors:["Ryan Coogler"],writers:["Ryan Coogler"],cast:[{name:"Michael B. Jordan",role:"Smoke / Stack"},{name:"Hailee Steinfeld",role:"Mary"},{name:"Miles Caton",role:"Sammie Moore"},{name:"Jack O'Connell",role:"Remmick"},{name:"Wunmi Mosaku",role:"Annie"},{name:"Jayme Lawson",role:"Pearline"}],studios:["Warner Bros. Pictures","Proximity Media"],country:"US"}},tv:{}};export{a as media,e as post};
